import {validateSnapshot,diagnoseRegion,positiveFactorScenario,calculateRsiSeries,thresholdPositions,assetEconomics,observationGate,matchingIndex,resolveRsiSelection} from './market-lab-math.js?v=1.30.6-plspo.5';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=v=>typeof v==='number'&&Number.isFinite(v);
const fmt=(v,d=2)=>finite(v)?new Intl.NumberFormat('ko-KR',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v):'판단 유보';
const safeUrl=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}};
const link=(url,label)=>{const u=safeUrl(url);return u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`:`<span>${esc(label)} · 유효한 공개 URL 없음</span>`;};
const TABS=[['diagnosis','시장 진단'],['scenario','조건 실험'],['ai','AI 숫자 검증'],['rsi','삼플레·RSI']];
const AXES=[['alpha','α','성장'],['beta','β','유동성'],['gamma','γ','심리']];
const original=(pages,text)=>`<details class="ml-original"><summary>원문 정의 · ${esc(pages)}</summary><p>${text}</p><p class="ml-muted">개인 소장 원문 아카이브. 짧은 인용과 쪽수만 표시하며 원본 사진은 공개하지 않습니다.</p></details>`;
const empty=text=>`<div class="ml-empty" role="status"><strong>관측 자료 없음</strong><p>${esc(text)}</p></div>`;

export function initMarketLabView({root,load,now=()=>new Date(),onReady,embeddedData}={}){
  if(!root)throw new Error('연구실 root가 필요합니다.');
  const query=new URLSearchParams(globalThis.location?.search||'');
  const state={tab:TABS.some(([v])=>v===query.get('lab-tab'))?query.get('lab-tab'):'diagnosis',region:query.get('lab-region')==='kr'?'kr':'us',phase:'idle',doc:null,error:'',marketId:null,priceIndex:null,rsiIndex:null,rsiOscIndex:null,rsiUnmatchedDate:null,manualRsi:'',scenario:{alpha:0,beta:0,gamma:0,weights:[1,1,1],sensitivity:0.1},economics:{},economicsResult:null,economicsError:'',hypothetical:false};
  let pending=null,readyCalled=false,chartWidth=0;
  const q=s=>root.querySelector(s);
  const sources=()=>state.doc?.sources||[];
  const sourceFor=id=>sources().find(s=>s.id===id);
  const markets=()=>state.doc?.markets?.filter(m=>m.region===state.region&&m.id!=='tqqq')||[];
  const selectedMarket=()=>markets().find(m=>m.id===state.marketId)||markets()[0];
  const tqqq=()=>state.doc?.markets?.find(m=>m.id==='tqqq');
  const updateUrl=()=>{try{const u=new URL(globalThis.location.href);u.searchParams.set('lab-tab',state.tab);u.searchParams.set('lab-region',state.region);globalThis.history.replaceState(globalThis.history.state,'',u);}catch{/* Sandboxed embeds may not own URL. */}};
  const sourceMeta=s=>s?`${esc(s.label)} · 단위 ${esc(s.unit)} · 최근 관측 ${esc(s.lastObservation||'미확인')} · 수집 ${esc(s.retrievedAt||'미확인')}`:'출처 연결 없음 · 판단 유보';
  function sourceDisclosure(){let notes='';try{if(state.doc)notes=(diagnoseRegion(state.doc,state.region,{now:now()}).notes||[]).map(n=>`<li>${esc(n)}</li>`).join('');}catch{notes='';}return `<details class="ml-sources"><summary>출처·시점·모형 한계${state.doc?` · ${sources().length}개 출처`:''}</summary><div class="ml-source-body"><p>스냅샷 생성 ${esc(state.doc?.generatedAt||'미수신')} · 모형 ${esc(state.doc?.modelVersion||'research-0.1')}</p><p>미국과 국내를 구분합니다. 국내 적용은 서비스의 새 가정으로, 원문 멘토 검증이 아닙니다. 수정 이력과 최초 공개 시점은 미확인입니다. 현재 자료로 과거 시점 백테스트를 재현했다고 주장하지 않습니다.</p><p>관측값은 연결된 스냅샷만 사용합니다. 실시간 호가·자동매매 모형이 아닙니다. 마지막 저장 관측의 종가이며 전망선이나 가상 가격을 섞지 않습니다.</p><p>원문 개념식 α × β × γ = SPX는 성장·유동성·심리를 함께 본다는 개념입니다. 실제 지수의 항등식이나 검증된 예측식이 아닙니다. 사진 158 / R8 p.163 · 사진 161 / R8 p.166. 축 선정·표준화·합성은 새 연구 가정입니다.</p><p>원문 개념과 새 연구 가정과 검증된 투자 규칙을 구분합니다. 확률·목표가·수익 보장은 없습니다.</p>${notes?`<ul class="ml-notes">${notes}</ul>`:''}${sources().map(s=>`<article><strong>${link(s.url,s.linkLabel||s.label)}</strong><p>${sourceMeta(s)} · 주기 ${esc(s.frequency||'미확인')} · 공개 시각 ${s.releaseTimeKnown?'확인':'미확인'}</p><p>${s.status==='ready'?'수집됨':'수집 오류'}${s.error?` · ${esc(s.error)}`:''}</p></article>`).join('')||'<p>출처 목록을 아직 받지 못했습니다. 데이터 다시 읽기를 사용하세요.</p>'}</div></details>`;}
  function shell(){root.classList.add('market-lab');root.setAttribute('aria-busy',String(state.phase==='loading'));const status=state.phase==='loading'?'자료를 읽고 있습니다. 조건 실험과 수기 계산은 사용할 수 있습니다.':state.phase==='error'?`자료 오류 · ${esc(state.error)} <button type="button" data-action="retry">데이터 다시 읽기</button>`:state.phase==='empty'?'스냅샷은 읽었지만 관측 자료가 없습니다. 없는 지표는 판단을 유보합니다.':'';const slot=document.getElementById('market-header-slot');if(slot){slot.hidden=false;slot.innerHTML=`<nav class="ml-tabs" role="tablist" aria-label="연구 도구">${TABS.map(([id,label])=>`<button type="button" role="tab" id="ml-tab-${id}" aria-controls="ml-panel" aria-selected="${state.tab===id}" tabindex="${state.tab===id?0:-1}" data-tab="${id}">${label}</button>`).join('')}</nav><div class="ml-region" role="group" aria-label="시장 지역"><button type="button" data-region="us" aria-pressed="${state.region==='us'}">미국</button><button type="button" data-region="kr" aria-pressed="${state.region==='kr'}">국내</button></div>`;}root.innerHTML=`<div class="ml-scroll">${status?`<div class="ml-status" aria-live="polite">${status}</div>`:''}<section id="ml-panel" role="tabpanel" aria-labelledby="ml-tab-${state.tab}" tabindex="0"></section>${sourceDisclosure()}</div>`;paintPanel();}
  function paintPanel(){const panel=q('#ml-panel');if(!panel)return;panel.innerHTML=state.tab==='diagnosis'?diagnosisView():state.tab==='scenario'?scenarioView():state.tab==='ai'?aiView():rsiView();paintCharts();if(state.tab==='scenario')paintScenario();if(state.tab==='rsi')paintThresholds();}
  function diagnosisView(){let result=null;try{if(state.doc)result=diagnoseRegion(state.doc,state.region,{now:now()});}catch(e){return `<div class="ml-error" role="alert">진단 계산을 유보합니다. ${esc(e.message)}</div>`;}
    const m=selectedMarket(),region=state.region==='us'?'미국':'국내';
    const shortUnit=(key,source)=>{const unit=source?.unit||'';if(key==='gamma')return unit.includes('pt')?'pt':unit.includes('%')?'%':'';return key==='alpha'?'전기비 %':'연율 %';};
    const scores=`<div class="ml-score-row">${AXES.map(([key,symbol,name])=>{const a=result?.axes?.find(x=>x.key===key);return `<article class="ml-axis ml-score ml-axis-${key}"><h3><span>${symbol}</span> ${name}</h3><strong class="ml-axis-value">${fmt(a?.z)}</strong><p class="ml-axis-stats"><span>${a?.status==='ready'?fmt(a.latest,a.source?.displayDecimals??2):'유보'} ${shortUnit(key,a?.source)}</span><span>${esc(a?.date||'관측일 없음')}</span></p>${a?.reason?`<p class="ml-warning">${esc(a.reason)}</p>`:''}</article>`;}).join('')}</div><p class="ml-score-total">${esc(result?.scoreLabel||'연구용 종합 점수')} <strong>${result?.status==='ready'?fmt(result.score):'판단 유보'}</strong></p>`;
    return `${scores}<article class="ml-card ml-price-card"><div class="ml-card-head"><h3>${region} 관측 차트</h3><label class="ml-inline">지수 <select data-control="market" aria-label="관측 지수 선택">${markets().map(x=>`<option value="${esc(x.id)}" ${x.id===m?.id?'selected':''}>${esc(x.name)} · ${esc(x.symbol)}</option>`).join('')||'<option>지역 관측 없음</option>'}</select></label></div>${m?`<div data-chart="price"></div>`:empty(`${region} 지수 가격이 없습니다. 미국 자료를 국내 관측으로 대체하지 않습니다.`)}</article>`;
  }
  function scenarioView(){const s=state.scenario;return `<div class="ml-section-heading"><div><span class="ml-kicker">가정 / 무차원</span><h2>음의 충격도, 방향을 잃지 않게</h2></div><span class="ml-pill">실제 관측과 분리</span></div><div class="ml-two-col"><article class="ml-card"><h3>가상 표준화 충격</h3><p class="ml-muted">각 축 −3~+3. 0은 중립 가정입니다. 관측값을 자동으로 가져오지 않습니다.</p>${AXES.map(([key,symbol,name],i)=>`<div class="ml-shock-row"><label for="ml-${key}">${symbol} ${name} <output id="ml-${key}-out">${fmt(s[key],1)}</output></label><input id="ml-${key}" data-shock="${key}" type="range" min="-3" max="3" step="0.1" value="${s[key]}" aria-describedby="ml-shock-help"><label class="ml-weight">가중치 <input data-weight="${i}" type="number" min="0" max="100" step="0.1" value="${s.weights[i]}" aria-label="${name} 비음수 가중치"></label></div>`).join('')}<p id="ml-shock-help" class="ml-muted">충격은 단위 없는 가정입니다. 가중치는 비음수이며 합이 1이 되도록 정규화합니다.</p><label class="ml-field">민감도 λ <input data-control="sensitivity" type="number" min="0" max="1" step="0.01" value="${s.sensitivity}"><small>기본 0.1은 임의 가정. 확정된 경제 계수가 아닙니다.</small></label><div class="ml-actions"><button type="button" data-action="negative">음수 두 축 반례</button><button type="button" data-action="reset-scenario">중립으로 초기화</button></div></article><article class="ml-card"><h3>가정 결과 · 기준 100</h3><div id="ml-scenario-output" aria-live="polite"></div><div class="ml-callout"><strong>가격 예측이 아닙니다</strong><p>가중합 압력을 양수 인자로 변환합니다. 두 음수를 곱해 양수가 되는 원시 곱셈의 해석 오류를 피할 뿐, 예측 정확도를 입증하지 않습니다.</p></div></article></div>`;}
  function paintScenario(){const target=q('#ml-scenario-output');if(!target)return;try{const s=state.scenario;if(![s.alpha,s.beta,s.gamma,...s.weights,s.sensitivity].every(finite)||s.weights.some(v=>v<0)||s.weights.reduce((a,b)=>a+b,0)<=0||s.sensitivity<0||s.sensitivity>1)throw new Error('가중치는 0 이상, 합은 0 초과로 입력하세요. λ는 0~1입니다.');const r=positiveFactorScenario(s);target.innerHTML=`<div class="ml-index"><strong>${fmt(r.index)}</strong><span>무차원 가상 지수 / 기준 100</span></div><p class="ml-formula">I = 100 × exp(λ × 압력)</p><p>부호 있는 압력 <b>${fmt(r.pressure,3)}</b> · λ ${fmt(s.sensitivity,2)}</p><div class="ml-table-wrap"><table><caption>축별 정규화 기여와 양수 인자</caption><thead><tr><th>축</th><th>충격</th><th>정규화 기여</th><th>양수 인자</th></tr></thead><tbody>${AXES.map(([key,sym,name],i)=>`<tr><th>${sym} ${name}</th><td>${fmt(s[key],1)}</td><td>${fmt(r.contributions[i],3)}</td><td>${fmt(r.factors[i],4)}</td></tr>`).join('')}</tbody></table></div><p class="ml-muted">동일 가중치와 λ=0.1은 새 연구 가정입니다. SPX 포인트·예상 수익률·백테스트 성과가 아닙니다.</p>`;}catch(e){target.innerHTML=`<p class="ml-error" role="alert">${esc(e.message)}</p>`;}}
  function aiView(){const e=state.economics;return `<div class="ml-section-heading"><div><span class="ml-kicker">원문 주장 → 검증할 숫자</span><h2>AI 기대를 현금으로 확인하기</h2></div><span class="ml-pill">현재 기업 실적 입력 없음</span></div><div class="ml-theme-grid"><article class="ml-card"><span class="ml-kicker">누적</span><h3>사용량이 매출로 남는가</h3><p>유료 과금 토큰량 × 실현 토큰단가. 사용자 결제 침투율은 별도로 봅니다.</p><p class="ml-muted">필요 증거: 기간별 사용량, 할인·무료분, 단가와 결제 고객 수. 연결된 실측값 없음 → 판단 유보.</p></article><article class="ml-card"><span class="ml-kicker">증명</span><h3>성장이 현금으로 이어지는가</h3><p>매출·영업이익률·FCF·CAPEX와 고객 집중도를 같은 기간·단위로 비교합니다.</p><p class="ml-muted">2027년은 원문에서 숫자 증명의 시기로 제시된 전망입니다. 달성된 사실이나 현재 실적이 아닙니다.</p></article><article class="ml-card"><span class="ml-kicker">자산화</span><h3>설비가 투자금을 회수하는가</h3><p>취득원가·내용연수·잔존가치와 실제 연간 운영현금을 분리합니다. 감가상각은 현금 유출이 아닙니다.</p><p class="ml-muted">ASP 30,000은 원문 판매가격 논의입니다. 제조원가·취득원가로 자동 대입하지 않습니다.</p></article></div><div class="ml-two-col ml-ai-calc"><article class="ml-card"><div class="ml-card-head"><h3>자산 현금흐름 계산기</h3><button type="button" data-action="economics-example">명시적 가상 예시 입력</button></div><p class="ml-muted">모든 금액은 선택한 동일 통화 단위로 입력하세요. 초기 입력값은 비워 둡니다.</p><form id="ml-economics-form"><div class="ml-input-grid">${[['costBasis','취득원가','0.01','0.01'],['residual','잔존가치','0','0.01'],['lifeYears','내용연수 (년)','1','1'],['annualRevenue','연간 현금 매출','0','0.01'],['annualOpex','연간 현금 운영비','0','0.01'],['discountRate','할인율 (%)','0','0.1']].map(([key,label,min,step])=>`<label class="ml-field" for="ml-econ-${key}">${label}<input id="ml-econ-${key}" name="${key}" data-econ="${key}" type="number" min="${min}" ${['lifeYears','discountRate'].includes(key)?'max="100"':''} step="${step}" required value="${esc(e[key]??'')}"></label>`).join('')}</div><button type="submit" class="ml-primary">현금흐름 계산</button></form></article><article class="ml-card"><h3>손익과 현금 구분</h3><div id="ml-economics-output" aria-live="polite">${economicsOutput()}</div><p class="ml-warning">세금·금융비용·교체투자·가동률 변동·운전자본은 제외한 새 단순화 가정입니다. 결과가 실제 사업가치나 매수 근거는 아닙니다.</p></article></div>${original('사진 197 / R8 p.208 · 198 / p.209 · 212 / p.226 · 216 / p.231 · 217 / p.232 · 221 / p.238','누적·증명·자산화라는 세 주제와 2027년 숫자 증명 전망을 출처에 귀속합니다. 미래 전망을 이미 실현된 재무값으로 표시하지 않습니다. 계산기는 원문 수익 약속이 아닌 별도의 연구용 가정입니다.')}`;}
  function economicsOutput(){if(state.economicsError)return `<p class="ml-error" role="alert">${esc(state.economicsError)}</p>`;const r=state.economicsResult;if(!r)return '<p class="ml-empty-copy">왼쪽에 원가와 현금흐름을 입력하면 손익·현금·현재가치를 나란히 계산합니다. 값이 없으면 결과를 만들지 않습니다.</p>';return `${state.hypothetical?'<p class="ml-pill ml-warn">가상 예시 결과 · 실제 기업 관측 아님</p>':'<p class="ml-pill">사용자 입력 가정 결과</p>'}<dl class="ml-results">${[['연간 감가상각',r.depreciation],['단순 가정 영업이익',r.operatingProfit],['연간 운영현금',r.operatingCash],['순현재가치 NPV',r.npv]].map(([l,v])=>`<div><dt>${l}</dt><dd>${fmt(v)}</dd></div>`).join('')}<div><dt>회수 구분</dt><dd>${esc(r.summary||'판단 유보')}</dd></div></dl><p class="ml-muted">입력 금액과 같은 통화·연말 수취를 가정합니다. 현금 매출과 현금 운영비가 같은 기간의 회계 수익·비용과 같다는 보장은 없습니다. 상각기간과 현금 수취기간은 현재 같은 내용연수를 씁니다. 감가상각은 현금 유출이 아닙니다.</p>`;}
  function rsiView(){const m=tqqq();return `<div class="ml-section-heading"><div><span class="ml-kicker">원문 규칙 / 미확인 구현</span><h2>삼플레는 세 전략, 한 종목이 아닙니다</h2></div></div><div class="ml-strategies"><article class="ml-card"><span class="ml-tag">미국 · 종목 확인</span><h3>TQQQ</h3><p>이 탭에서 종가·참고 RSI를 관측 데이터로 계산하는 유일한 전략입니다.</p></article><article class="ml-card"><span class="ml-tag">국내 · 구두 식별</span><h3>KODEX 코스닥150 레버리지</h3><p>정확한 종목코드는 미확인. 실행 가능한 매매 전략으로 제공하지 않습니다.</p></article><article class="ml-card"><span class="ml-tag">반도체 · 구두 표현만</span><h3>‘속쓸’</h3><p>티커와 세부 규칙 미확인. 임의의 종목으로 치환하지 않습니다.</p></article></div><div class="ml-risk"><strong>‘손절 없음’은 무위험이 아닙니다.</strong><p>원문 TQQQ 설명에 한정된 표현입니다. 일일 3배 레버리지 ETF는 일일 재설정·변동성 누적 손실·경로 의존성과 장기 손실 위험이 있습니다. 장기 수익률이 지수의 3배라는 뜻이 아닙니다.</p><p>${link('https://www.proshares.com/our-etfs/leveraged-and-inverse/tqqq','ProShares 공식 TQQQ 상품·위험 설명')}</p></div><div class="ml-two-col"><article class="ml-card"><h3>TQQQ 관측 종가 + 참고 RSI</h3><p class="ml-source-line">${sourceMeta(sourceFor(m?.sourceId))}</p>${m?'<div data-chart="rsi-price"></div><div data-chart="rsi"></div>':empty('TQQQ 종가가 없습니다. 계산 RSI는 표시하지 않으며 수기 입력 비교는 가능합니다.')}<p class="ml-muted">마지막 제공된 완료 세션 종가 기준. 실제 계산: 종가 Wilder 14, 초기 14개 변화의 평균, 신호 SMA 9. 평균 상승폭과 평균 하락폭이 모두 0일 때만 RSI 50입니다. 최근 봉의 보합 전체가 50은 아닙니다. 키움 RSI 원본 내보내기가 없어 동등성은 유보입니다. GDP 과거 공표 판본이 없어 실시간 백테스트도 유보입니다.</p></article><article class="ml-card"><h3>키움 수기값과 별도로 비교</h3><label class="ml-field" for="ml-manual-rsi">키움 일봉 RSI 14 수기 입력 (0~100)<input id="ml-manual-rsi" data-control="manual-rsi" type="number" min="0" max="100" step="0.01" value="${esc(state.manualRsi)}" placeholder="미입력"></label><div id="ml-thresholds" aria-live="polite"></div><div class="ml-callout"><strong>거리 비교만 제공합니다</strong><p>원문 매수 기준 33.5 / 29.5, 매도 기준 40 / 43. 미만·이하·돌파 등 비교 연산, 비중, 3차 매수, 재진입, 이익 실현 우선순위는 미확인입니다.</p></div></article></div><details class="ml-original"><summary>원문 조건과 계산 구현의 미확인 차이</summary><p>원문은 키움 일봉 14 + 신호 9를 요구합니다. 키움의 정확한 평활 방식·가격 종류·세션/시간 기준을 검증하지 못했습니다. 이 화면의 Wilder/SMA 계산과 수기 키움값은 독립된 값입니다. 자동 주문·검증된 승률·세 전략 동시 실행을 제공하지 않습니다.</p></details>${original('사진 238 / R8 p.252 · 사진 239 / R8 p.254 · 사진 240 / R8 p.255','짧은 수치 인용: 매수 <q>33.5 / 29.5</q>, 매도 <q>40 / 43</q>. <q>손절 없음</q>은 TQQQ 설명에만 귀속합니다. 이 인용만으로 완전한 매매 엔진을 복원할 수 없습니다.')}`;}
  function marketGate(market){const source=sourceFor(market?.sourceId),gate=observationGate({generatedAt:state.doc?.generatedAt,source,prices:market?.prices,now:now(),timeZone:market?.timezone||source?.timezone});return market?{...gate,market}:{ok:false,reason:'출처가 연결되지 않았습니다.'};}
  function rsiGate(){const market=tqqq(),gate=marketGate(market);if(!gate.ok)return {ok:false,reason:gate.reason.includes('미래')?'미래 수집·생성 시각의 RSI는 현재 관측으로 표시하지 않습니다.':gate.reason.includes('가격일')?'미래 가격일의 RSI는 표시하지 않습니다.':gate.reason.replace('출처가 연결되지 않았습니다.','TQQQ 출처가 연결되지 않았습니다.')};return gate;}
  function rsiRows(){const gate=rsiGate();if(!gate.ok)return [];try{return calculateRsiSeries(gate.market.prices,14,9);}catch{return [];}}
  function paintThresholds(){const el=q('#ml-thresholds');if(!el)return;const gate=rsiGate(),rows=rsiRows().filter(r=>finite(r.rsi)),manual=state.manualRsi===''?null:Number(state.manualRsi);const valid=manual!==null&&finite(manual)&&manual>=0&&manual<=100;if(state.rsiUnmatchedDate){el.innerHTML=`${gate.ok?'':`<p class="ml-warning">${esc(gate.reason)} 계산 RSI는 숨기고 수기 비교만 둡니다.</p>`}<p class="ml-warning">${esc(state.rsiUnmatchedDate)}에는 계산 RSI가 없습니다. 이전 기준선 표를 이 날짜의 값으로 읽지 마세요.</p><p>수기 키움 RSI <strong>${valid?fmt(manual):'미입력 / 판단 유보'}</strong></p>`;return;}const index=state.rsiOscIndex==null?Math.max(0,rows.length-1):Math.max(0,Math.min(rows.length-1,Number(state.rsiOscIndex))),selected=rows[index]||null,latest=rows.at(-1)||null;const dateNote=selected?`기준선 표 ${selected.date}${latest&&selected.date!==latest.date?' · 마지막 완료 관측 '+latest.date+'과 다름':' · 마지막 완료 관측'}`:'계산 RSI 없음';el.innerHTML=`${gate.ok?'':`<p class="ml-warning">${esc(gate.reason)} 계산 RSI는 숨기고 수기 비교만 둡니다.</p>`}<div class="ml-mini-results"><p>계산 RSI <strong>${fmt(selected?.rsi)}</strong> · ${esc(dateNote)}</p><p>계산 신호 SMA9 <strong>${fmt(selected?.signal)}</strong></p><p>수기 키움 RSI <strong>${valid?fmt(manual):'미입력 / 판단 유보'}</strong></p></div>${state.manualRsi!==''&&!valid?'<p class="ml-error">0~100 범위의 수기 RSI를 입력하세요.</p>':''}<p class="ml-muted">위치는 반올림 전 수치입니다. 차트에서 고른 과거일을 마지막 관측의 주문 시점으로 읽지 마세요.</p>${[['계산 RSI',selected?.rsi],['수기 키움 RSI',valid?manual:null]].map(([label,value])=>{if(!finite(value))return '';return `<div class="ml-table-wrap"><table><caption>${label}와 원문 기준선의 거리 · 주문 신호 아님</caption><thead><tr><th>원문 기준</th><th>수치</th><th>차이 (RSI pt)</th><th>위치</th></tr></thead><tbody>${thresholdPositions(value).map(t=>`<tr><th>${esc(t.label)}</th><td>${fmt(t.threshold,1)}</td><td>${fmt(t.difference,Math.abs(t.difference)<0.05?6:2)}</td><td>${esc(({below:'아래',equal:'같음',above:'위'})[t.position]||'유보')}</td></tr>`).join('')}</tbody></table></div>`;}).join('')}`;}
  function chartMarkup({id,points,unit,label,selected,lines=[],rsi=false,signal=[]}){
    const pts=points.filter(p=>p&&finite(p[1]));if(!pts.length)return empty(`${label}에 유효한 수치가 없습니다.`);
    const width=Math.max(200,Math.round(q(`[data-chart="${id}"]`)?.clientWidth||640)),height=rsi?220:290,pad={l:64,r:20,t:24,b:36};
    const vals=pts.map(p=>p[1]).concat(signal.filter(p=>finite(p[1])).map(p=>p[1]));let low=rsi?0:Math.min(...vals),high=rsi?100:Math.max(...vals);if(low===high){const extra=Math.max(Math.abs(low)*0.02,1);low-=extra;high+=extra;}else if(!rsi){const extra=(high-low)*0.1;low-=extra;high+=extra;}if(!rsi)low=Math.max(0,low);
    const x=i=>pad.l+(pts.length===1?0.5:i/(pts.length-1))*(width-pad.l-pad.r),y=v=>pad.t+(high-v)/(high-low)*(height-pad.t-pad.b);
    const path=pts.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(2)},${y(p[1]).toFixed(2)}`).join(' ');
    const index=selected===null||selected===undefined?pts.length-1:Math.max(0,Math.min(pts.length-1,selected)),point=pts[index];
    const sigPath=signal.map((p,i)=>finite(p[1])?`${i&&finite(signal[i-1]?.[1])?'L':'M'}${x(i).toFixed(2)},${y(p[1]).toFixed(2)}`:'').join(' ');
    return `<figure class="ml-chart"><figcaption><strong>${esc(label)}</strong><span>${esc(point[0])} · ${fmt(point[1])} ${esc(unit)}</span></figcaption><svg viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-labelledby="ml-chart-${id}-title ml-chart-${id}-desc"><title id="ml-chart-${id}-title">${esc(label)} · ${pts.length}개 관측</title><desc id="ml-chart-${id}-desc">${esc(pts[0][0])}부터 ${esc(pts.at(-1)[0])}. 선택일 ${esc(point[0])}, ${fmt(point[1])} ${esc(unit)}. 실제 관측만 연결하며 끝과 시작을 닫지 않습니다.</desc>${Array.from({length:5},(_,i)=>{const v=low+(high-low)*i/4;return `<line class="ml-grid-line" x1="${pad.l}" x2="${width-pad.r}" y1="${y(v)}" y2="${y(v)}"/><text class="ml-axis-label" x="${pad.l-8}" y="${y(v)+4}" text-anchor="end">${fmt(v,rsi?0:1)}</text>`;}).join('')}${lines.map((l,i)=>`<line class="ml-threshold-line" x1="${pad.l}" x2="${width-pad.r}" y1="${y(l)}" y2="${y(l)}"/><text class="ml-threshold-label" x="${pad.l+20+i*(width-pad.l-pad.r-40)/3}" y="${y(l)-4}" text-anchor="middle">${l}</text>`).join('')}<path class="ml-observed-line ${rsi?'ml-rsi-line':''}" d="${path}"/>${sigPath?`<path class="ml-signal-line" d="${sigPath}"/>`:''}<line class="ml-crosshair" x1="${x(index)}" x2="${x(index)}" y1="${pad.t}" y2="${height-pad.b}"/><circle class="ml-chart-point" cx="${x(index)}" cy="${y(point[1])}" r="4"/><text class="ml-axis-label" x="${pad.l}" y="${height-10}">${esc(pts[0][0])}</text><text class="ml-axis-label" x="${width-pad.r}" y="${height-10}" text-anchor="end">${esc(pts.at(-1)[0])}</text></svg><label class="ml-date-selector">관측일 선택 <input type="range" min="0" max="${pts.length-1}" step="1" value="${index}" data-date="${id}" aria-label="${esc(label)} 관측일" aria-valuetext="${esc(point[0])}, ${fmt(point[1])} ${esc(unit)}" ${pts.length===1?'disabled':''}></label>${rsi?'<p class="ml-chart-legend"><span>Wilder RSI14</span><span>SMA9 신호</span> · 점선은 원문 기준</p>':''}</figure>`;
  }
  function hiddenChart(reason){return `<p class="ml-warning">${esc(reason)} 가격 차트는 숨깁니다.</p>`;}
  function paintCharts(){const m=selectedMarket(),p=q('[data-chart="price"]');if(p){const gate=marketGate(m);p.innerHTML=gate.ok?chartMarkup({id:'price',points:m.prices||[],unit:m.unit,label:`${m.name} 관측 종가`,selected:state.priceIndex}):hiddenChart(gate.reason);}const tm=tqqq(),rp=q('[data-chart="rsi-price"]');if(rp){const gate=rsiGate();rp.innerHTML=gate.ok?chartMarkup({id:'rsi-price',points:tm.prices||[],unit:tm.unit,label:'TQQQ 관측 종가',selected:state.rsiIndex}):hiddenChart(gate.reason);}const rr=q('[data-chart="rsi"]');if(rr){const rows=rsiRows().filter(r=>finite(r.rsi));rr.innerHTML=chartMarkup({id:'rsi',points:rows.map(r=>[r.date,r.rsi]),unit:'RSI pt',label:'참고 RSI14 · 키움 동등성 미검증',selected:state.rsiOscIndex,lines:[29.5,33.5,40,43],rsi:true,signal:rows.map(r=>[r.date,r.signal])});}}
  function syncObservedDate(kind,index){if(kind==='price'){state.priceIndex=index;paintCharts();return;}const prices=tqqq()?.prices||[],rows=rsiRows().filter(r=>finite(r.rsi));if(kind==='rsi-price'){const picked=resolveRsiSelection(prices,rows,index);state.rsiIndex=picked.rsiIndex;state.rsiOscIndex=picked.rsiOscIndex;state.rsiUnmatchedDate=picked.unmatched?picked.date:null;}else{state.rsiUnmatchedDate=null;state.rsiOscIndex=index;const price=matchingIndex(prices,rows[index]?.date);if(price!==null)state.rsiIndex=price;}paintCharts();paintThresholds();}
  function submitEconomics(){state.economicsError='';try{const e=state.economics,keys=['costBasis','residual','lifeYears','annualRevenue','annualOpex','discountRate'];if(keys.some(k=>e[k]===''||e[k]===undefined||!Number.isFinite(Number(e[k]))))throw new Error('모든 항목에 명시적인 숫자를 입력하세요.');const args=Object.fromEntries(keys.map(k=>[k,Number(e[k])]));args.discountRate/=100;state.economicsResult=assetEconomics(args);}catch(e){state.economicsResult=null;state.economicsError=e.message;}const el=q('#ml-economics-output');if(el)el.innerHTML=economicsOutput();}
  document.getElementById('market-header-slot')?.addEventListener('click',event=>{const el=event.target.closest('button');if(el.dataset.region){state.region=el.dataset.region;state.marketId=null;state.priceIndex=null;updateUrl();shell();document.querySelector(`[data-region="${state.region}"]`)?.focus();return;}if(el.dataset.tab){state.tab=el.dataset.tab;updateUrl();shell();document.querySelector(`[data-tab="${state.tab}"]`)?.focus();}});root.addEventListener('click',event=>{const el=event.target.closest('button');if(!el||!root.contains(el))return;if(el.dataset.tab){state.tab=el.dataset.tab;updateUrl();shell();document.querySelector(`[data-tab="${state.tab}"]`)?.focus();}else if(el.dataset.region){state.region=el.dataset.region;state.marketId=null;state.priceIndex=null;updateUrl();shell();q(`[data-region="${state.region}"]`)?.focus();}else if(el.dataset.action==='retry'){state.phase='idle';pending=null;render();}else if(el.dataset.action==='negative'){state.scenario={alpha:-2,beta:-2,gamma:0,weights:[1,1,1],sensitivity:0.1};paintPanel();}else if(el.dataset.action==='reset-scenario'){state.scenario={alpha:0,beta:0,gamma:0,weights:[1,1,1],sensitivity:0.1};paintPanel();}else if(el.dataset.action==='economics-example'){state.economics={costBasis:100000,residual:10000,lifeYears:5,annualRevenue:40000,annualOpex:15000,discountRate:8};state.hypothetical=true;state.economicsResult=null;paintPanel();submitEconomics();}});
  root.addEventListener('keydown',event=>{const tab=event.target.closest('[role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const i=TABS.findIndex(([id])=>id===state.tab),next=event.key==='Home'?0:event.key==='End'?3:(i+(event.key==='ArrowRight'?1:3))%4;state.tab=TABS[next][0];updateUrl();shell();document.querySelector(`[data-tab="${state.tab}"]`)?.focus();});
  root.addEventListener('input',event=>{const el=event.target;if(el.dataset.shock){state.scenario[el.dataset.shock]=Number(el.value);q(`#ml-${el.dataset.shock}-out`).textContent=fmt(Number(el.value),1);paintScenario();}else if(el.dataset.weight!==undefined){state.scenario.weights[Number(el.dataset.weight)]=el.value===''?NaN:Number(el.value);paintScenario();}else if(el.dataset.control==='sensitivity'){state.scenario.sensitivity=el.value===''?NaN:Number(el.value);paintScenario();}else if(el.dataset.control==='manual-rsi'){state.manualRsi=el.value;paintThresholds();}else if(el.dataset.econ){state.economics[el.dataset.econ]=el.value;state.hypothetical=false;state.economicsResult=null;state.economicsError='';q('#ml-economics-output').innerHTML='<p class="ml-muted">입력값이 변경되었습니다. 현금흐름 계산을 눌러 다시 계산하세요.</p>';}});
  root.addEventListener('change',event=>{const el=event.target;if(el.dataset.control==='market'){state.marketId=el.value;state.priceIndex=null;paintPanel();}else if(el.dataset.date){syncObservedDate(el.dataset.date,Number(el.value));q(`[data-date="${el.dataset.date}"]`)?.focus();}});
  root.addEventListener('submit',event=>{if(event.target.id==='ml-economics-form'){event.preventDefault();submitEconomics();}});
  if(typeof ResizeObserver!=='undefined'){const observer=new ResizeObserver(entries=>{const w=Math.round(entries[0]?.contentRect.width||0);if(w&&w!==chartWidth){chartWidth=w;paintCharts();}});observer.observe(root);}
  async function render(){if(state.phase!=='idle'&&state.phase!=='loading'){shell();return state;}if(pending)return pending;state.phase='loading';shell();pending=(async()=>{try{let doc;if(embeddedData!==undefined)doc=typeof embeddedData==='string'?JSON.parse(embeddedData):embeddedData;else if(load){const loaded=await load('./data/market-lab.json');doc=typeof loaded==='string'?JSON.parse(loaded):typeof loaded?.json==='function'?await loaded.json():loaded;}else{const res=await fetch('./data/market-lab.json');if(!res.ok)throw new Error(`자료 응답 HTTP ${res.status}`);doc=await res.json();}state.doc=validateSnapshot(doc);state.phase=(state.doc?.markets?.some(m=>m.prices?.length)||Object.values(state.doc?.regions||{}).some(r=>Object.values(r.axes||{}).some(a=>a.values?.length)))?'loaded':'empty';state.error='';}catch(e){state.doc=null;state.phase='error';state.error=e?.message||'자료를 읽지 못했습니다.';}finally{shell();if(!readyCalled){readyCalled=true;try{onReady?.();}catch{/* Boot callbacks cannot hide the research view. */}}}return state;})();return pending;}
  return {render,state};
}
